def later_heading_preimage(path, data):
    pins = LATER_HEADING_BYTES.get(path)
    if pins is None or hashlib.sha256(data).hexdigest() != pins[1]:
        return data
    for current, prior in pins[2]:
        if data.count(current) != 1:
            raise ValueError('Exact later heading anchor required: ' + path)
        data = data.replace(current, prior, 1)
    if hashlib.sha256(data).hexdigest() != pins[0]:
        raise ValueError('Exact later heading preimage required: ' + path)
    return data


def restore(path, data):
    if path == "cart.php":
        data = later_heading_preimage(path, data)
    pins = HASHES.get(path)
    if pins is None or hashlib.sha256(data).hexdigest() != pins[0]:
        return data
    restored = data
    for old, new in COPIES[path]:
        old, new = old.encode(), new.encode()
        if restored.count(new) != 1:
            raise ValueError('Exact shipping copy anchor required: ' + path)
        restored = restored.replace(new, old, 1)
    if hashlib.sha256(restored).hexdigest() != pins[1]:
        raise ValueError('Shipping copy restoration must equal exact preimage: ' + path)
    return restored
